object LeafIcons {
    private fun symbol(name: String, vararg paths: String, mirror: Boolean = false): ImageVector {
        val builder = ImageVector.Builder(name = "MaterialSymbols.Rounded.$name",
            defaultWidth = 24.dp, defaultHeight = 24.dp,
            viewportWidth = 960f, viewportHeight = 960f, autoMirror = mirror)
        builder.addGroup(name = "viewport", translationY = 960f)
        paths.forEach { data -> builder.addPath(
            pathData = PathParser().parsePathString(data).toNodes(), fill = SolidColor(Color.Black)) }
        builder.clearGroup()
        return builder.build()
    }
