    private fun svg(name: String, vararg paths: String): ImageVector {
        val builder = ImageVector.Builder(name = "MaterialSymbols.Rounded.$name",
            defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 960f, viewportHeight = 960f)
        paths.forEach { data -> builder.addPath(
            pathData = PathParser().parsePathString(data).toNodes(), fill = SolidColor(Color.Black)) }
        return builder.build()
    }
