    fun warmUp() {
        listOf<Any>(LeafIcons, LeafFilledIcons).forEach { holder ->
            holder.javaClass.methods.forEach { method ->
                if (method.name.startsWith("get") && method.parameterCount == 0 && method.returnType == ImageVector::class.java) {
                    runCatching { method.invoke(holder) }
                }
            }
        }
    }
